{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Naltrexone, the closest analogue (Morgan 0.7119) sharing the 6-keto-14-hydroxy phenolic morphinan scaffold, had an absolute oral bioavailability of ~5% in healthy male volunteers due to extensive first-pass hepatic metabolism; this directly supports a low-F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Naltrexone is reported to have very poor oral bioavailability of about 5–10% in patients, providing additional direct evidence that this scaffold with a 6-keto and 14-hydroxy group is prone to low systemic exposure after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Another absolute bioavailability study of naltrexone reported 20%, at the threshold, showing that even the higher estimates for the closest analogue do not clearly exceed the 20% cutoff.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "One naltrexone study reported 60% absolute oral bioavailability, a contradictory outlier among multiple lower estimates; because the consensus for the closest analogue is poor/low, this does not overturn the low prediction.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C46"],
      "claim": "Nalmefene, a less similar analogue with a 6-methylene instead of 6-keto, had F ~53% with food; this higher value is less transferable because the query retains the 6-keto group associated with low naltrexone bioavailability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue naltrexone (Morgan 0.7119) shares the 6-keto-14-hydroxy phenolic morphinan core and consistently shows poor/low oral bioavailability, with most estimates around 5–20% and occasional higher values. Less similar analogues with altered C6 substituents or different scaffolds show higher F, but the direct structural match to naltrexone supports a low (<20%) absolute oral bioavailability prediction for oxymorphone.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability data for oxymorphone itself were provided.",
    "Naltrexone bioavailability estimates are heterogeneous (5–60%), introducing uncertainty in the exact magnitude of first-pass effect.",
    "The impact of the N-methyl versus N-cyclopropylmethyl substituent on first-pass metabolism is not directly quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

